import type { CodeRef, CSharpClassMap, CSharpRegistrationKind } from "./types.js";
import csharpClassMapJson from "./csharpClassMap.json" with { type: "json" };

const csharpClassMap = csharpClassMapJson as CSharpClassMap;

/**
 * Resolves one C# name from game JSON against the committed `csharpClassMap.json` (generated by
 * `scripts/map-csharp-classes.ts`), trying each registry in `kinds` in order. Unknown names (engine,
 * VSEssentials, mod DLLs) come back as a bare `{role, name}` with no type/link.
 */
export function resolveCodeRef(kinds: CSharpRegistrationKind[], role: CodeRef["role"], name: string): CodeRef {
  for (const kind of kinds) {
    const loc = csharpClassMap.registrations[kind]?.[name];
    if (!loc) continue;
    const url = loc.path
      ? `https://github.com/${csharpClassMap.repo}/blob/${csharpClassMap.commit}/${loc.path}${loc.line ? `#L${loc.line}` : ""}`
      : undefined;
    return { role, name, type: loc.type, ...(url ? { path: loc.path, url } : {}) };
  }
  return { role, name };
}
